/**
 * Parity contract with the shared C# term form model. The fixture is generated by
 * `SecurityAssetTermFormParityFixtureTests` (tests/Meridian.Tests/SecurityMaster) from
 * `SecurityAssetClassRegistry` and `SecurityAssetTermFormModel`: every registry asset class's
 * served fields, pickable scalar fields in form order and closed value choices, plus the C#
 * validation verdict of every editor kind over a fixed input corpus. This suite replays the same
 * fixture through the TypeScript mirror, so the two lanes cannot drift silently: a schema or
 * form-rule change regenerates the fixture and fails here until the mirror follows.
 */

import { describe, expect, it } from "vitest";
import parityFixture from "@/test/fixtures/security-asset-term-form-parity.json";
import type {
  SecurityAssetClassDefinition,
  SecurityAssetTermEditorKind,
  SecurityAssetTermFieldDefinition
} from "@/lib/api/security-master-schema.api";
import {
  buildSchemaFieldGroups,
  buildSchemaValueEditor,
  validateSchemaFieldValue
} from "./security-passport-schema-fields.view-model";

interface ParityValidationCase {
  value: string;
  error: string | null;
}

interface ParityValidationContract {
  editor: string;
  required: boolean;
  label: string;
  choices: string[];
  cases: ParityValidationCase[];
}

interface ParityAssetClass {
  assetClass: string;
  termsVersion: number;
  lotUnit: string;
  cashFlowBehavior: string;
  fields: SecurityAssetTermFieldDefinition[];
  pickableFieldKeys: string[];
  valueChoicesByKey: Record<string, string[]>;
}

const assetClasses = parityFixture.assetClasses as unknown as ParityAssetClass[];
const validationContracts = parityFixture.validationContracts as unknown as ParityValidationContract[];

describe("term form parity with SecurityAssetTermFormModel", () => {
  it("carries every registry asset class and every editor contract", () => {
    expect(assetClasses.length).toBeGreaterThan(0);
    expect(validationContracts.length).toBeGreaterThan(0);
    // Every editor kind the API client declares appears in the fixture, required and optional.
    const editors = new Set(validationContracts.map((contract) => contract.editor));
    for (const editor of ["Text", "Decimal", "Integer", "Toggle", "Date", "Identifier", "Choice", "Convention", "Json"]) {
      expect(editors, `fixture is missing editor kind ${editor}`).toContain(editor);
    }
  });

  for (const assetClass of assetClasses) {
    it(`mirrors ${assetClass.assetClass}'s pickable fields and value choices`, () => {
      const definition: SecurityAssetClassDefinition = {
        assetClass: assetClass.assetClass,
        termsVersion: assetClass.termsVersion,
        lotUnit: assetClass.lotUnit,
        cashFlowBehavior: assetClass.cashFlowBehavior,
        fields: assetClass.fields
      };

      // The C# model lists pickable fields in flat declared order; the browser groups them into
      // sections. Parity is about the facts, not the presentation: the same field set, driven by
      // the same declared order, with each section keeping that order internally.
      const groups = buildSchemaFieldGroups(definition);
      const pickable = groups.flatMap((group) => group.fields);
      const byDeclaredOrder = [...pickable].sort((a, b) => a.order - b.order);
      expect(byDeclaredOrder.map((field) => field.key)).toEqual(assetClass.pickableFieldKeys);
      for (const group of groups) {
        const orders = group.fields.map((field) => field.order);
        expect(orders, `group ${group.group} keeps declared order`).toEqual([...orders].sort((a, b) => a - b));
      }

      for (const field of pickable) {
        expect(
          buildSchemaValueEditor(field).choices,
          `value choices for ${assetClass.assetClass}.${field.key}`
        ).toEqual(assetClass.valueChoicesByKey[field.key]);
      }
    });
  }

  for (const contract of validationContracts) {
    it(`validates ${contract.editor}${contract.required ? " (required)" : ""} like the C# form model`, () => {
      const field: SecurityAssetTermFieldDefinition = {
        key: "testField",
        fieldPath: "assetSpecificTerms.testField",
        label: contract.label,
        type: contract.editor,
        editor: contract.editor as SecurityAssetTermEditorKind,
        group: "Parity",
        order: 0,
        required: contract.required,
        scalarEditable: true,
        choices: contract.choices,
        aliases: []
      };

      for (const parityCase of contract.cases) {
        expect(
          validateSchemaFieldValue(field, parityCase.value),
          `input ${JSON.stringify(parityCase.value)}`
        ).toBe(parityCase.error);
      }
    });
  }
});
